                    "【C01】适用与课程登记\n本办法适用于生产部门普通员工参加与当前岗位直接相关的外部课程，不适用于职能部门或外协单位人员。申请填写岗位、课程内容、举办机构、计划时间与费用承担部门，生产主管核对岗位相关性。员工只说明“参加培训”而未说明部门时，制度维护人员先确认归属，不因为课程名称包含办公或技术就判断其部门。"
