              "text": "费用票据核验指引\n模拟制度 / 演示数据\n星桥制造有限公司（虚构）\n制度编号：INVOICE；版本：2026；状态：active\n生效日期：2026-01-01；失效日期：未设定\n部门范围：公司各部门（业务对象以正文适用条款为准）；维护部门：财务部\n文件用途：本文件为产品设计与测试虚构的普通企业制度，不代表真实企业规定、法律意见或现场作业指令。业务对象以正文适用条款为准，部门范围不构成系统访问权限。\n\n【C01】用途与责任\n本指引适用于员工公务费用报销中的票据核验，支持差旅和培训审核；它只规定票据检查动作，不授予业务费用报销资格。费用是否属于公司承担范围，应同时核对有效差旅或培训制度。员工提交票据，财务负责核验，业务主管对实际业务的确认不能直接代替财务对票据真实性及一致性的检查。\n\n【C02】票据一致性\n发票抬头应为星桥制造有限公司，发票金额、日期、业务内容应与对应申请一致。抬头错误的发票退回更正，员工应联系开票方重新开具或依法更正后再次提交；提交人的姓名出现在订单中不能替代公司抬头。财务记录退回原因与原申请编号，避免同一张错误票据被作为另一事项重新申报。\n\n【C03】电子票据验真\n电子发票在报销审核中须完成验真并登记验真结果，保存电子原文件以便复核。电子发票符合其他核验要求时，无需额外提交纸质打印件；打印一份电子发票也不增加其真实性。验真服务暂时不可用时，记录待核验状态，等待完成核验后继续审批，不能因文件能够打开就认为验真已经通过。\n\n【C04】缺失与替代材料\n缺失发票时由员工联系开票方补开，补齐前不进入付款环节。支付截图、银行卡扣款信息、课程报名截图或酒店订单仅能作辅助说明，不可直接替代有效发票。申请人应说明实际支付与退款情况，对确实无法补开的个案交财务核验；本指引没有设置用固定比例打折报销替代补票的规则。\n\n【C05】重复与退回\n财务核对发票号码、金额和原申请记录，发现同一张发票已用于其他报销时，暂停本次票据审核并要求经办人说明，不能重复申报相同支出。误上传的票据由申请人更正材料，保留更正记录；撤回申请不自动使该发票成为尚未使用的凭据，应核对原事项是否已支付或退款。",
