              "text": "采购验收与对公结算管理办法\n模拟制度 / 演示数据\n星桥制造有限公司（虚构）\n制度编号：ACCEPTANCE；版本：2026；状态：active\n生效日期：2026-01-01；失效日期：未设定\n部门范围：公司各部门（业务对象以正文适用条款为准）；维护部门：采购部\n文件用途：本文件为产品设计与测试虚构的普通企业制度，不代表真实企业规定、法律意见或现场作业指令。业务对象以正文适用条款为准，部门范围不构成系统访问权限。\n\n【C01】范围与单据\n本办法适用于公司采购货物或服务的到货验收及供应商对公结算，与采购需求审批制度配套使用。员工差旅报销不按本办法的验收角色和付款周期办理。经办人以采购申请及订单编号关联交付记录，分批到货时分别记录数量与日期，不能仅凭一张供应商送货单认定全部合同已经履行。\n\n【C02】普通到货验收\n非关键物资到货后，由仓库保管员核对数量和外观，再由需求部门确认规格和使用要求。收货签字表示完成相应接收检查，不等于供应商可以立即收到全部款项。数量短缺或规格不符应记录差异并通知采购经办人，不能为了赶付款日期先填写与实际不符的验收结论。\n\n【C03】关键设备复核\n关键生产设备除仓库和需求部门验收外，还须由质量部门复核；缺少质量复核记录时不视为验收材料齐全。采购事前批准的是需求及预算，不能替代设备到货后的实际质量检查。设备由供应商安排人员安装的，同时核对外协入场手续，设备验收记录不授予安装人员自由通行权限。\n\n【C04】异常物资\n验收发现不合格或数量异常时，记录异常、隔离待处理并通知采购经办人，待确认处理结果后更新记录。供应商提供说明或承诺补货不能自动改变原异常结论，需求部门也不能以生产急用直接把异常写成合格。本条不规定每一种质量缺陷的责任比例、罚款或保修期限，个案需核对合同与事实。\n\n【C05】结算材料\n供应商对公结算应具备采购批准记录、合同或订单、验收记录和有效发票四类材料，材料应对应同一供应商和采购事项。任何一类缺失均先补正，再提交完整结算审核；发票证明开票事项但不替代验收，验收合格也不能省略财务对合同、发票和付款条件的核对。",
              "valid": false,
              "supporting_anchors": [],
              "reason": "未支持实际回答中的适用事实或明确资料边界；来源噪声。"
