              "text": "采购需求与授权审批办法\n模拟制度 / 演示数据\n星桥制造有限公司（虚构）\n制度编号：PURCHASE；版本：2025；状态：expired\n生效日期：2025-01-01；失效日期：2025-12-31\n部门范围：公司各部门（业务对象以正文适用条款为准）；维护部门：采购部\n文件用途：本文件为产品设计与测试虚构的普通企业制度，不代表真实企业规定、法律意见或现场作业指令。业务对象以正文适用条款为准，部门范围不构成系统访问权限。\n\n【C01】业务范围\n本办法适用于公司为生产及职能业务购买货物或服务的需求申请，员工个人差旅和培训报销不属于本流程。需求部门填写采购用途、规格、数量、预算和期望交付时间，采购部协调供应商信息。已有供应商联系方式不等于取得下单授权，采购经办人应先取得与采购事项相符的审批记录。\n\n【C02】金额口径\n审批金额以同一采购事项含税总金额为准，不能拆单降低审批层级。同一事项包含运输或安装等合同内费用时，一并按含税总额核对。预算只是计划金额，供应商报价变化导致总额跨越审批门槛时重新核对层级，不以原预算低于门槛为由跳过新的审批要求。\n\n【C03】审批门槛\n含税总额不超过5000元，由部门负责人审批；超过5000元且不超过30000元，由部门负责人和财务负责人审批；超过30000元，由部门负责人、财务负责人和总经理审批。边界金额按“不超过”计入本档，审批记录应写明该采购事项与金额，不用其他部门相似采购的批准作为本事项授权。\n\n【C04】询价与紧急事项\n采购部整理可核对的供应商报价和交付条件，需求人提供技术或用途说明。紧急停线需求也须先完成相应金额层级审批，不能因口头标注“加急”就绕过授权。事后补充资料需要对应原事项与实际变更原因，本文件没有规定紧急事项天然免除书面记录或财务核验。\n\n【C05】下单前检查\n批准后由采购经办人核对规格、交付地址、含税价格及付款条件，合同或订单变化时核对是否影响审批金额与业务范围。审批仅授权按获批事项推进，不证明货物已合格，也不代替供应商对公结算中的验收材料。供应商提交发票不构成货物已按要求交付的独立证明。",
              "valid": false,
              "supporting_anchors": [],
              "reason": "未支持实际回答中的适用事实或明确资料边界；来源噪声。"
