                      "text": "【C07】旧版归档\n本版自2025年1月1日生效，2025年12月31日失效，2026年的新采购需求应使用采购审批2026版。旧门槛5000元与30000元只保留用于历史资料，不构成当前授权；审批模板未及时更新时，应以有效制度核对而不是沿用表格中的旧档位。"
