                    "【C02】年度预算\n生产部门每名普通员工每个自然年外部培训报销上限为1800元，个人剩余额度按1800元减去当年已报销培训费用计算。该额度不自动发放，也不是任何课程都可使用的无条件福利；实际报销仍需满足审批、岗位相关性及票据材料要求。课程变更或退费应登记，以免重复占用或重复申报同一费用。"
