              "text": "【C06】信息使用\n请假证明仅交办理请假登记和核验的人员，不在公开群组扩散个人证明内容。制度问答使用请假类型、工作日数量和材料要求，不需要上传真实诊断详情作为一般咨询背景。制度维护人员对材料缺项提出具体补正要求，不能凭一般问答自动确认员工健康状态或决定待遇。\n\n【C07】制度边界与解释\n本文件不规定年假天数和病假工资计算比例；没有可用条款时应由人力资源部查核适用的其他正式制度，不能把社会常识直接当成本公司的已发布规定。本版自2026年1月1日生效，维护人员按有效版本答复事假审批和病假证明问题；请假天数、培训完成证明和发票验真证明属于不同业务概念。\n\n【C08】登记差异处理\n实际返岗日期与原计划不一致时，员工向直属主管说明差异，人力资源部按实际涉及的工作日核对申请及销假记录。请假类型变化时保留原申请和变更说明，避免把病假材料当成事假的一般审批附件使用。登记人员只记录已核验事实，不凭同事转述填写诊断或假期待遇；对没有制度依据的问题，记录为待确认事项并联系维护部门。因工作交接尚未完成而需要主管协调时，应明确待办任务，不能用工作台账上的未完成状态推定员工请假申请已经被自动撤销。\n\n文件结束｜模拟制度 / 演示数据｜条款编号用于证据定位，不表示已实现产品引用功能。",
