              "text": "员工请假与证明材料管理办法\n模拟制度 / 演示数据\n星桥制造有限公司（虚构）\n制度编号：LEAVE；版本：2026；状态：active\n生效日期：2026-01-01；失效日期：未设定\n部门范围：公司各部门（业务对象以正文适用条款为准）；维护部门：人力资源部\n文件用途：本文件为产品设计与测试虚构的普通企业制度，不代表真实企业规定、法律意见或现场作业指令。业务对象以正文适用条款为准，部门范围不构成系统访问权限。\n\n【C01】适用与登记\n本办法适用于生产和职能部门普通员工的事假、病假申请登记，岗位排班安排由所在部门协调。员工应填写请假种类、起止日期、工作交接事项及联系方式，主管核对工作交接后按相应权限办理。对跨班次的请假先明确实际涉及的工作日，不能只按自然日数量推定是否达到审批或证明门槛。\n\n【C02】事假审批层级\n事假不超过2个工作日由直属主管审批，超过2个工作日由直属主管和部门负责人共同审批。审批人员核对请假期间与交接安排，不能将主管确认收到申请视为部门负责人已经同意。员工对预计时长有变更时更新原申请并按累计工作日重新核对审批层级，不用拆成多个短申请绕过要求。\n\n【C03】申请时间与紧急补办\n员工原则上提前1个工作日提交事假申请。突发紧急情况可先联系直属主管说明情况，并在返岗后1个工作日内补办；补办仍应记录实际休假时间与工作交接。紧急联系不是对无限期请假的批准，员工延长请假应及时更新预计返岗时间，由主管协调工作安排。\n\n【C04】病假证明\n连续病假达到3个工作日时，应提供医疗机构出具的证明，注明可核对的就诊与休息信息。主管接收材料后转人力资源部核验登记，医疗证明的提交本身不代表病假相关工资或待遇已确定。本条未设定连续病假不足3个工作日一律无需任何材料的规则，遇此类具体材料问题应向人力资源部确认。\n\n【C05】交接与销假\n请假人列明待办任务、资料存放位置和代理联系人，返岗后核对实际休假期间并办理销假。生产岗位涉及排班时由主管协调当班交接，职能岗位按任务期限安排代理；代理人只能在本人原有权限范围内处理事项。工作交接记录不代替请假审批，也不等于代理人获得申请人的全部审批权限。\n\n【C06】信息使用\n请假证明仅交办理请假登记和核验的人员，不在公开群组扩散个人证明内容。制度问答使用请假类型、工作日数量和材料要求，不需要上传真实诊断详情作为一般咨询背景。制度维护人员对材料缺项提出具体补正要求，不能凭一般问答自动确认员工健康状态或决定待遇。\n\n【C07】制度边界与解释\n本文件不规定年假天数和病假工资计算比例；没有可用条款时应由人力资源部查核适用的其他正式制度，不能把社会常识直接当成本公司的已发布规定。本版自2026年1月1日生效，维护人员按有效版本答复事假审批和病假证明问题；请假天数、培训完成证明和发票验真证明属于不同业务概念。\n\n【C08】登记差异处理\n实际返岗日期与原计划不一致时，员工向直属主管说明差异，人力资源部按实际涉及的工作日核对申请及销假记录。请假类型变化时保留原申请和变更说明，避免把病假材料当成事假的一般审批附件使用。登记人员只记录已核验事实，不凭同事转述填写诊断或假期待遇；对没有制度依据的问题，记录为待确认事项并联系维护部门。因工作交接尚未完成而需要主管协调时，应明确待办任务，不能用工作台账上的未完成状态推定员工请假申请已经被自动撤销。\n\n文件结束｜模拟制度 / 演示数据｜条款编号用于证据定位，不表示已实现产品引用功能。",
