              "text": "生产部门岗位培训费用管理办法\n模拟制度 / 演示数据\n星桥制造有限公司（虚构）\n制度编号：TRAIN-PROD；版本：2026；状态：active\n生效日期：2026-01-01；失效日期：未设定\n部门范围：生产部门普通员工；维护部门：人力资源部\n文件用途：本文件为产品设计与测试虚构的普通企业制度，不代表真实企业规定、法律意见或现场作业指令。业务对象以正文适用条款为准，部门范围不构成系统访问权限。\n\n【C01】适用与课程登记\n本办法适用于生产部门普通员工参加与当前岗位直接相关的外部课程，不适用于职能部门或外协单位人员。申请填写岗位、课程内容、举办机构、计划时间与费用承担部门，生产主管核对岗位相关性。员工只说明“参加培训”而未说明部门时，制度维护人员先确认归属，不因为课程名称包含办公或技术就判断其部门。\n\n【C02】年度预算\n生产部门每名普通员工每个自然年外部培训报销上限为1800元，个人剩余额度按1800元减去当年已报销培训费用计算。该额度不自动发放，也不是任何课程都可使用的无条件福利；实际报销仍需满足审批、岗位相关性及票据材料要求。课程变更或退费应登记，以免重复占用或重复申报同一费用。\n\n【C03】报名与批准\n报名付费前须取得直属主管和生产部门负责人的书面批准，并由人力资源部登记培训计划。直属主管同意不等于生产部门负责人已批准，登记成功也不能替代两项书面批准。变更课程内容或增加费用时重新提交变更材料，保留原批准记录与新的确认信息，以便审核人员核对。\n\n【C04】报销与差旅衔接\n培训报销材料为培训批准记录、培训发票、课程介绍和完成培训证明，提交期限及付款时限按有效员工费用报销办法执行。参加外地课程发生的公务交通和住宿，按有效差旅办法另行申请及报销，不挤占本条外部课程费用的年度额度；同一张票据不能同时作为课程费和住宿费重复申报。\n\n【C05】额度结余\n未使用的年度额度不能转给其他员工，也不能结转至下一自然年。合班或团体报名仍按每名员工的实际课程费用与年度剩余额度核对，部门总预算充足不意味着个人上限自动提高。员工调入生产部门时先由人力资源部核对当年已使用记录，本条不规定调岗后能再领取一份完整额度。",
              "valid": true,
              "supporting_anchors": [],
              "reason": "回答明确列出该文件所覆盖业务或历史范围，片段支持该资料边界说明；不把边界列表当作具体待遇依据。"
