              "text": "员工费用报销管理办法\n模拟制度 / 演示数据\n星桥制造有限公司（虚构）\n制度编号：EXPENSE；版本：2026；状态：active\n生效日期：2026-01-01；失效日期：未设定\n部门范围：公司各部门（业务对象以正文适用条款为准）；维护部门：财务部\n文件用途：本文件为产品设计与测试虚构的普通企业制度，不代表真实企业规定、法律意见或现场作业指令。业务对象以正文适用条款为准，部门范围不构成系统访问权限。\n\n【C01】业务范围\n本办法适用于普通员工的已批准公务费用报销；差旅、培训分别先满足对应有效业务制度。供应商对公采购结算按采购审批与验收制度办理，不适用员工个人报销的提交和付款时限。员工本人同时是采购经办人时，应按业务性质区分，不能因为提交人是员工就把供应商款项改成个人费用。\n\n【C02】提交时限\n差旅费用在出差结束后7个工作日内提交完整申请，培训费用在课程结束后7个工作日内提交完整申请。只有把必备材料提交到报销流程才算提交，个人保存草稿或给同事发票照片不算。申请人应在事项结束后整理材料，对可能影响时限的缺件向直属主管说明，本条没有规定逾期即永久失去报销资格。\n\n【C03】差旅材料\n差旅报销须有经审批的出差申请、有效发票和行程说明；住宿发票应注明入住日期与离店日期。票据日期、地点或金额与获批行程不同的，附差异说明供审核核对。直属主管的聊天回复、酒店订单和支付截图可以作为辅助材料，但不能直接替代本条要求的获批申请及有效发票。\n\n【C04】培训材料\n培训报销须有有效培训批准记录、培训发票、课程介绍和完成培训证明。培训批准的具体人员、预算和适用部门按有效培训制度核对，不能仅凭课程有结业证就判断符合公司全部报销条件。课程延期或取消时，应更新实际发生情况及退款信息，只有实际发生且有制度依据的费用进入审核。\n\n【C05】审批与付款\n申请先由直属主管核实业务真实性，再由财务审核票据。审核通过且无待补材料后，财务在3个工作日内付款；退回补件期间不属于审核通过后的付款等待期。财务发现收款信息或费用金额与材料不一致时，应退回核对，不得仅凭主管同意就跳过票据审核和信息检查。\n\n【C06】异常交接\n缺失发票、重复票据、电子发票验真和抬头错误按《费用票据核验指引》处理。申请退回时列明缺少项目，申请人保留原申请编号补正后重新提交。补齐材料不代表审核自动通过，财务仍需核对业务一致性。本制度没有赋予报销助手审批、发放款项或决定个案罚款的权限。\n\n【C07】归档与版本\n财务部维护报销制度清单、审核记录和付款凭证，申请人可凭申请编号查询办理状态。制度维护人员发现模板引用旧版本时应更正模板并提示经办人核对，不得把模板文字优先于有效制度。本版自2026年1月1日生效，替代2025版；当前提交时限为7个工作日、审核通过后付款时限为3个工作日。\n\n【C08】退回材料记录\n财务退回申请时列明申请编号、缺项材料和需核对的业务差异，保留申请人原始提交时间及本次退回时间。经办人回复补件时按清单逐项说明新增材料，不另造一个已经审核通过的申请编号；原流程中的批准记录应能与新提交材料对应。没有明确的审核通过记录时，不能把“已收件”“已登记”或“待付款核对”解释为最终批准。本条仅规定材料追踪方法，不设退回一次即终止申请的次数限制，也不据此改变当年有效制度中的提交和付款时限。\n\n文件结束｜模拟制度 / 演示数据｜条款编号用于证据定位，不表示已实现产品引用功能。",
