                      "text": "【C01】适用与登记\n本办法适用于生产和职能部门普通员工的事假、病假申请登记，岗位排班安排由所在部门协调。员工应填写请假种类、起止日期、工作交接事项及联系方式，主管核对工作交接后按相应权限办理。对跨班次的请假先明确实际涉及的工作日，不能只按自然日数量推定是否达到审批或证明门槛。"
