                      "text": "【C01】适用对象\n本办法适用于入厂维修、安装等作业的外协人员，普通商务洽谈和参观访客另按访客制度办理。公司内部联系人登记作业单位、人员名单、区域和计划时间，明确与采购订单或作业任务的对应关系。供应商同时承担商务洽谈和安装时，依据实际进入目的分别核对，不用一次访客预约覆盖全部活动。"
