            "question": "业务适用日期：2026-10-01\n用户部门：未提供（本题不预设部门）\n问题：公司普通员工每年有多少天带薪年假？",
            "timestamp": "2026-10-01T10:22:59.164Z",
            "visible_answer": "**可以确认**\n- 现行《员工请假与证明材料管理办法》（LEAVE，2026版）不规定年假天数和病假工资计算比例。 [1]\n- 该办法规定没有可用条款时应由人力资源部查核适用的其他正式制度，不能把社会常识直接当成本公司的已发布规定。 [1]\n\n**当前制度无法确认**\n- 当前候选资料未提供公司普通员工每年带薪年假的具体天数，因此无法确认该数额。",
