              "text": "员工境内差旅管理办法\n模拟制度 / 演示数据\n星桥制造有限公司（虚构）\n制度编号：TRAVEL；版本：2026；状态：active\n生效日期：2026-01-01；失效日期：未设定\n部门范围：公司各部门（业务对象以正文适用条款为准）；维护部门：行政部\n文件用途：本文件为产品设计与测试虚构的普通企业制度，不代表真实企业规定、法律意见或现场作业指令。业务对象以正文适用条款为准，部门范围不构成系统访问权限。\n\n【C01】适用与行程登记\n本办法适用于生产部门及职能部门普通员工的境内公务出差，不适用于外协人员、访客或私人旅行。申请应写明业务任务、出差城市、起止日期和费用承担部门；跨城市行程逐段登记，日期及城市变化应在原申请下更新。生产员工外出参加与岗位相关的课程，同时涉及差旅和培训时，分别按两个有效制度核对费用性质，不能把培训审批当成出差审批。\n\n【C02】出发前审批\n员工至少提前3个工作日提交出差申请，由直属主管审批。申请未完成前不按已批准行程办理公司承担的预订；紧急任务应在申请中说明原因，但本办法不设口头同意自动替代审批的流程。已批准行程的目的地或日期发生变化时，在原申请中提交变更说明，由直属主管确认后按变更行程执行。\n\n【C03】住宿标准\n北京、上海、深圳住宿费上限为每人每晚550元，其他境内城市为每人每晚380元。额度按实际公务住宿夜数核算，未发生住宿不发放等额补贴，实际费用低于上限时按实际合规费用申请。公务结束后的私人延住应与公务住宿分开列示，不能仅因同一张酒店订单就把全部住宿纳入出差费用。\n\n【C04】交通标准\n普通员工高铁报销限二等座，飞机报销限经济舱。市内公务交通凭有效票据据实申请，同时注明路线、日期和公务事由；私人游览或家属同行的交通支出不属于员工公务交通。退改签应附原订单、变更说明及退款记录，以净实际支出申请，不得同时申报已退回的原票金额。\n\n【C05】超标审批\n住宿预计超出标准时，须在预订前取得部门负责人的书面批准，批准记录列明城市、日期、原因和预计金额。直属主管审批出差只确认任务必要性，不能自动替代部门负责人的住宿超标批准。条款要求办理批准，但没有设定未获批准时的具体处罚、扣款金额或一律不予报销的处理结论，遇此类个案应提交财务核验。",
