                      "text": "【C05】超标审批\n住宿预计超出标准时，须在预订前取得部门负责人的书面批准，批准记录列明城市、日期、原因和预计金额。直属主管审批出差只确认任务必要性，不能自动替代部门负责人的住宿超标批准。条款要求办理批准，但没有设定未获批准时的具体处罚、扣款金额或一律不予报销的处理结论，遇此类个案应提交财务核验。"
