                      "text": "【C06】跨制度交接\n报销提交期限、必备材料及付款时限，统一按有效《员工费用报销管理办法》执行；发票异常按有效《费用票据核验指引》处理。住宿发票应能核对入住和离店日期，出差申请、实际行程和票据存在差异时先附解释材料。差旅标准本身不构成财务审核通过的承诺，资料完整也仍需按报销审批顺序流转。"
