                      "text": "【C07】归档与执行\n行政部维护有效版本、出差申请和变更记录，财务保存费用审核材料。制度咨询应提供部门、城市及发生日期，缺少关键事实时由维护人员核对后答复。本版自2026年1月1日生效并替代2025版；2026年发生的境内差旅使用本版550元和380元标准，不因旧申请模板仍显示旧金额而继续使用旧标准。"
