                      "text": "【C07】维护与边界\n行政部维护本版预约流程、接待区域与联系人信息，自2026年1月1日起生效。维修安装人员即使曾以商务访客身份来过，也应按本次实际作业目的使用外协入场制度。本办法只覆盖预约、登记、陪同和拍摄许可，不推定个人消费由公司承担或未经批准的区域可自由开放。"
