                      "text": "【C07】制度边界与解释\n本文件不规定年假天数和病假工资计算比例；没有可用条款时应由人力资源部查核适用的其他正式制度，不能把社会常识直接当成本公司的已发布规定。本版自2026年1月1日生效，维护人员按有效版本答复事假审批和病假证明问题；请假天数、培训完成证明和发票验真证明属于不同业务概念。"
