                  "text": "员工境内差旅管理办法\n模拟制度 / 演示数据\n星桥制造有限公司（虚构）\n制度编号：TRAVEL；版本：2025；状态：expired\n生效日期：2025-01-01；失效日期：2025-12-31\n部门范围：公司各部门（业务对象以正文适用条款为准）；维护部门：行政部\n文件用途：本文件为产品设计与测试虚构的普通企业制度，不代表真实企业规定、法律意见或现场作业指令。业务对象以正文适用条款为准，部门范围不构成系统访问权限。\n\n【C01】适用与立项\n本办法适用于生产部门及职能部门普通员工的境内公务出差，不适用于外协人员、访客或员工私人出行。出差任务应写明目的、地点、起止日期和费用承担部门；同一行程涉及多个目的地时，在申请中逐段说明。员工所在部门负责确认业务必要性，行政负责行程登记。仅有会议邀请不能代替内部出差申请，费用承担部门应与出差申请保持一致。\n\n【C02】出发前审批\n员工至少提前2个工作日提交出差申请，由直属主管审批；未完成审批不得按已批准行程预订公司承担的交通和住宿。行程日期或目的地发生变化时，应在原申请下补充变更说明并重新提交直属主管确认。紧急任务的申请仍应明确实际出发日期及紧急原因，制度不设置口头同意自动替代审批的规则。\n\n【C03】住宿额度\n北京、上海、深圳住宿费上限为每人每晚500元，其他境内城市为每人每晚350元。住宿额度是实际发生费用的报销上限，不是按天直接发放的补贴；两人合住也应分别写明对应人员和实际支付金额。员工应留存入住、离店日期与出差行程的对应关系，私人延住的夜数不列入公务住宿申请。\n\n【C04】交通与票据\n普通员工高铁报销限二等座，飞机报销限经济舱。市内公务交通应保留有效票据并写明起讫地点与公务事项，私人游览交通不在公务交通范围。行程单用于说明路线，支付记录用于说明付款事实，二者不自动等同于合规发票。发生退票或改签时，应将原订单、变更原因和实际退款一并登记。\n\n【C05】住宿超标事项\n超过住宿上限时，应在预订前取得部门负责人的书面批准，并将超标原因、预计金额和批准记录附在出差申请后。审批记录应对应具体城市、日期和住宿订单，不能作为今后所有行程的通用授权。仅有直属主管同意并不替代部门负责人对住宿超标事项的书面批准。\n\n【C06】材料交接\n出差完成后员工整理出差申请、行程说明、交通住宿票据，按有效报销制度提交财务。行政登记行程不代表财务已经审核票据，也不代表费用已付款；财务可对日期、人员和费用承担部门不一致的材料要求补充说明。员工应将公务费用和私人支出分开列示，便于审核人员核对。\n\n【C07】归档与版本\n行政部保存获批申请及变更记录，财务保存报销材料；需要调阅时说明业务目的与申请编号。本版自2025年1月1日施行，2025年12月31日失效，已由2026版替代。保留本文件仅用于历史存档，不得将本版金额用于2026年发生的新差旅事项；遇到文件摘录与版本页不一致时先核对完整文件。\n\n【C08】台账核对\n行政在每月第3个工作日核对上月尚未完成资料交接的出差申请，台账包括申请编号、出差人、费用承担部门、实际出发和返回日期、批准及变更记录。该台账核对日是行政的内部检查节点，不改变员工的报销提交期限；经办人不能等到月度核对后才着手收集材料。行政发现同一申请出现两个不同版本的审批说明时，应保留原记录并注明核对结论，不直接覆盖历史审批内容。业务部门收到待补清单后逐项补充实际行程信息，财务是否进入付款仍按对应有效报销流程核对。\n\n文件结束｜模拟制度 / 演示数据｜条款编号用于证据定位，不表示已实现产品引用功能。\n",
