                      "text": "【C07】归档与版本\n财务部维护报销制度清单、审核记录和付款凭证，申请人可凭申请编号查询办理状态。制度维护人员发现模板引用旧版本时应更正模板并提示经办人核对，不得把模板文字优先于有效制度。本版自2026年1月1日生效，替代2025版；当前提交时限为7个工作日、审核通过后付款时限为3个工作日。"
